import{_ as n,c as t,o as i,a3 as r}from"./chunks/framework.CoV49S2T.js";const h=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/faq.md","filePath":"de/guide/faq.md","lastUpdated":1786612388000}'),a={name:"de/guide/faq.md"};function s(o,e,p,l,d,u){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p><strong>F: Was ist ClipboardxAI?</strong></p><p>A: ClipboardxAI ist ein intelligenter Zwischenablagen-Manager für macOS. Er hält einen durchsuchbaren Verlauf aller kopierten Inhalte vor und ermöglicht es, Aktionen darauf auszuführen — zusammenfassen, übersetzen, Text aufräumen oder an ein Cloud-KI-Modell senden.</p><p><strong>F: Welche macOS-Versionen werden unterstützt?</strong></p><p>A: macOS 14 Sonoma oder neuer, optimiert für Apple Silicon (M-Serie) mit Intel-Unterstützung.</p><p><strong>F: Wie installiere ich es?</strong></p><p>A: Laden Sie es aus dem <a href="/de/">Mac App Store</a> (empfohlen) herunter oder holen Sie sich den neuesten Build von <s><a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub Releases</a></s>. Siehe die <a href="/de/guide/installation.html">Installationsanleitung</a>.</p><p><strong>F: Ist ClipboardxAI kostenlos?</strong></p><p>A: ClipboardxAI ist eine kostenpflichtige App im Mac App Store. Nach dem Kauf sind alle eingebauten lokalen Werkzeuge enthalten und es wird kein Konto benötigt. Cloud-KI-Aktionen verwenden den API-Schlüssel <em>Ihres eigenen</em> Anbieters, sodass Sie den KI-Anbieter direkt bezahlen — es gibt keine zusätzliche kostenpflichtige Stufe in der App.</p><p><strong>F: Welche KI-Anbieter werden unterstützt?</strong></p><p>A: Jeder OpenAI-kompatible Anbieter: DeepSeek, MiniMax, Zhipu GLM, Kimi (Moonshot), Mistral und lokales Ollama — plus OpenAI, Anthropic und Gemini. Ihr Schlüssel wird im Keychain gespeichert.</p><p><strong>F: Funktioniert es offline?</strong></p><p>A: Ja. Zwischenablagen-Verlauf und die eingebauten lokalen Werkzeuge (extract links, count stats, collapse blank lines und mehr) laufen vollständig auf Ihrem Mac ohne Internetverbindung.</p><p><strong>F: Sind meine Zwischenablagen-Daten privat?</strong></p><p>A: Ihr Verlauf bleibt auf Ihrem Gerät. Cloud-KI ist opt-in und sendet Inhalte nur an den von Ihnen konfigurierten Anbieter, unter Verwendung eines Schlüssels aus Ihrem Keychain. Wir empfangen oder speichern Ihre Einträge niemals, und es gibt keine Telemetrie. Siehe die <a href="/de/guide/privacy.html">Datenschutzerklärung</a>.</p><p><strong>F: Wie füge ich weitere Aktionen hinzu?</strong></p><p>A: Durchsuchen Sie den <a href="/de/marketplace/">Marketplace</a> und klicken Sie bei einer Aktion auf <strong>Install</strong>. Dadurch wird die App über einen Deep-Link geöffnet und sie erscheint in Ihrer Liste <strong>Installed</strong>.</p><p><strong>F: Wie aktualisiere ich die App?</strong></p><p>A: Die Mac-App-Store-Version wird automatisch aktualisiert. <s>Für GitHub-Builds laden Sie das neueste Release herunter und ersetzen die App in <code>Applications</code>.</s></p><p><strong>F: Wie melde ich Fehler oder schlage Funktionen vor?</strong></p><p>A: Öffnen Sie ein Issue im <a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub-Repository</a>. Geben Sie Ihre macOS-Version, App-Version und Schritte zur Reproduktion an.</p><p><strong>F: Wo werden meine Daten gespeichert?</strong></p><p>A: Im sandboxed-Container:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.clipboard/Data/Library/Application Support/com.w3cub.clipboard/</span></span></code></pre></div><p>API-Schlüssel liegen im systemeigenen Keychain, nicht in diesem Ordner.</p>',25)])])}const g=n(a,[["render",s]]);export{h as __pageData,g as default};
